import assert from 'node:assert/strict';
import { test } from 'node:test';
import { Readable } from 'node:stream';
import sharp from 'sharp';
import { EventEmitter } from 'node:events';
import { setImmediate as tick } from 'node:timers/promises';
import { createCoverArtVariantScheduler } from '../../src/services/image/coverArtVariantScheduler';
import { adminCatalogArtworkSource, legacyCatalogArtworkUrl } from '../../src/administration/catalog/adminCatalogArtworkSource';
import { isPublicArtworkAddress, loadLegacyCatalogArtwork, type LegacyArtworkDependencies } from '../../src/administration/catalog/adminLegacyArtwork';

const address = { address: '8.8.8.8', family: 4 };
const url = 'https://images.example.test/legacy.png';
const png = () => sharp({ create: { width: 4, height: 3, channels: 3, background: '#123456' } }).png().toBuffer();
const fixture = (body: Buffer, overrides: Partial<LegacyArtworkDependencies> = {}): LegacyArtworkDependencies => ({
    lookup: async () => [address],
    request: async () => ({ statusCode: 200, headers: { 'content-type': 'image/png', 'content-length': String(body.length) }, body: Readable.from([body]) }),
    ...overrides
});

test('private artwork source never emits a legacy URL or bypasses an explicit invalid image identity', () => {
    const id = 'a'.repeat(24);
    assert.deepEqual(adminCatalogArtworkSource({ coverArtId: id, coverArtUrl: url }), { kind: 'stored', imageId: id, reference: `id:${id}` });
    assert.equal(adminCatalogArtworkSource({ coverArtId: 'invalid', coverArtUrl: url }), null);
    assert.deepEqual(adminCatalogArtworkSource({ coverArtUrl: `/content/images/${id}` }), { kind: 'stored', imageId: id, reference: `url:/content/images/${id}` });
    assert.deepEqual(adminCatalogArtworkSource({ coverArtUrl: url }), { kind: 'external', url, reference: url });
    for (const value of [null, '', '//images.example.test/a', '/unrelated/a', 'https://user:pass@example.test/a',
        'http://example.test/a', 'https://127.0.0.1/a', 'https://[::1]/a', 'https://example.test:444/a',
        'https://example.test/a#fragment', 'https://example.test./a', 'https://example.test/a\nprivate',
        'https://example.test/\\private', 'https://example.test/' + 'x'.repeat(2048)]) {
        assert.equal(legacyCatalogArtworkUrl(value), null);
    }
});

test('DNS policy rejects private, mapped, reserved and mixed-family answers', () => {
    for (const ip of ['0.1.2.3', '10.0.0.1', '100.64.0.1', '127.0.0.1', '169.254.169.254', '172.16.0.1',
        '192.168.0.1', '192.0.2.1', '198.18.0.1', '198.51.100.1', '203.0.113.1', '224.0.0.1', '255.255.255.255']) {
        assert.equal(isPublicArtworkAddress({ address: ip, family: 4 }), false, ip);
    }
    for (const ip of ['::1', '::ffff:8.8.8.8', 'fc00::1', 'fe80::1', 'ff00::1', '2001:db8::1', '2002:0808:0808::1', '3fff::1']) {
        assert.equal(isPublicArtworkAddress({ address: ip, family: 6 }), false, ip);
    }
    assert.equal(isPublicArtworkAddress(address), true);
    assert.equal(isPublicArtworkAddress({ address: '2606:4700:4700::1111', family: 6 }), true);
    assert.equal(isPublicArtworkAddress({ address: '8.8.8.8', family: 6 }), false);
});

test('a validated public DNS answer is pinned and complete raster output is converted to static WebP', async () => {
    const input = await png(); let requested = false;
    const output = await loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
        request: async (target, pinned, signal) => {
            requested = true; assert.equal(target.href, url); assert.deepEqual(pinned, address); assert.equal(signal.aborted, false);
            return { statusCode: 200, headers: { 'content-type': 'image/png', 'content-length': String(input.length) }, body: Readable.from([input]) };
        }
    }));
    assert.equal(requested, true);
    const metadata = await sharp(output).metadata();
    assert.equal(metadata.format, 'webp'); assert.equal(metadata.width, 4); assert.equal(metadata.height, 3);
});

test('any private DNS answer prevents HTTPS, even after a public answer', async () => {
    let requests = 0;
    for (const addresses of [[], [address, { address: '169.254.169.254', family: 4 }]]) {
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
            lookup: async () => addresses, request: async () => { requests++; throw new Error('must not connect'); }
        }));
    }
    assert.equal(requests, 0);
});

test('unsafe redirects, active content, encoding and oversized or truncated bodies fail closed', async () => {
    const input = await png();
    for (const response of [
        { statusCode: 302, headers: { location: 'https://127.0.0.1/private', 'content-type': 'image/png' }, body: input },
        { statusCode: 200, headers: { 'content-type': 'image/svg+xml' }, body: Buffer.from('<svg/>') },
        { statusCode: 200, headers: { 'content-type': 'image/png', 'content-encoding': 'gzip' }, body: input },
        { statusCode: 200, headers: { 'content-type': 'image/png', 'content-length': String(10 * 1024 * 1024 + 1) }, body: input },
        { statusCode: 200, headers: { 'content-type': 'image/png', 'content-length': String(input.length + 1) }, body: input },
        { statusCode: 200, headers: { 'content-type': 'image/jpeg' }, body: input },
        { statusCode: 200, headers: { 'content-type': 'image/png' }, body: input.subarray(0, 40) }
    ]) {
        const stream = Readable.from([response.body]);
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
            lookup: async () => [address], request: async () => ({ ...response, body: stream })
        }));
        assert.equal(stream.destroyed, true);
    }
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
        request: async () => ({ statusCode: 200, headers: { 'content-type': 'image/png' }, body: Readable.from([Buffer.alloc(10 * 1024 * 1024 + 1)]) })
    })));
});

test('an aborted request and a stalled DNS lookup never outlive the shared deadline', async () => {
    const controller = new AbortController(); controller.abort();
    await assert.rejects(loadLegacyCatalogArtwork(url, controller.signal, { lookup: async () => [address] }));
    const started = Date.now();
    const keepAlive = setTimeout(() => undefined, 1000);
    try { await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, { deadlineMs: 10, lookup: async () => new Promise(() => undefined) })); }
    finally { clearTimeout(keepAlive); }
    assert.ok(Date.now() - started < 1000);
});

test('the shared deadline destroys a stalled upstream body before any image can be returned', async () => {
    let sent = false;
    const body = new Readable({ read() { if (!sent) { sent = true; this.push(Buffer.from('partial')); } } });
    const keepAlive = setTimeout(() => undefined, 1000);
    try {
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
            deadlineMs: 10, lookup: async () => [address],
            request: async () => ({ statusCode: 200, headers: { 'content-type': 'image/png' }, body })
        }));
        assert.equal(body.destroyed, true);
    } finally { clearTimeout(keepAlive); }
});

test('production HTTPS transport pins one DNS answer, verifies the original TLS host and forwards no credentials', async () => {
    const input = await png(); let called = false;
    await loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async () => [address],
        httpsRequest: ((target: URL, options: any, respond: (response: any) => void) => {
            called = true; assert.equal(target.href, url); assert.equal(options.agent, false);
            assert.equal(options.servername, 'images.example.test'); assert.equal(options.rejectUnauthorized, true);
            assert.equal(options.family, 4); assert.equal(options.autoSelectFamily, false);
            assert.deepEqual(Object.keys(options.headers).sort(), ['Accept', 'Accept-Encoding', 'User-Agent']);
            assert.equal(options.headers['User-Agent'], 'Finitude/1.0 (administrator artwork preview; https://kashewt.com)');
            options.lookup('untrusted-second-lookup.example', { all: false }, (error: unknown, ip: string, family: number) => {
                assert.equal(error, null); assert.equal(ip, address.address); assert.equal(family, 4);
            });
            options.lookup('untrusted-second-lookup.example', { all: true }, (error: unknown, addresses: unknown) => {
                assert.equal(error, null); assert.deepEqual(addresses, [address]);
            });
            const outgoing = new EventEmitter() as EventEmitter & { end: () => void };
            outgoing.end = () => respond(Object.assign(Readable.from([input]), {
                statusCode: 200, headers: { 'content-type': 'image/png', 'content-length': String(input.length) }
            }));
            return outgoing;
        }) as NonNullable<LegacyArtworkDependencies['httpsRequest']>
    });
    assert.equal(called, true);
});

test('the real legacy process pool caps two requests, bounds the per-account queue and removes cancelled work', async () => {
    const input = await png(); await tick();
    const releases: Array<(failure?: boolean) => void> = []; let active = 0, peak = 0, requests = 0;
    const dependencies: LegacyArtworkDependencies = {
        lookup: async () => [address], clientKey: 'same-synthetic-admin',
        request: async () => {
            active++; requests++; peak = Math.max(peak, active);
            return new Promise(resolve => releases.push((failure = false) => {
                active--; resolve({ statusCode: failure ? 302 : 200, headers: { 'content-type': 'image/png' }, body: Readable.from([input]) });
            }));
        }
    };
    const controllers = Array.from({ length: 10 }, () => new AbortController());
    const tasks = controllers.map(controller => loadLegacyCatalogArtwork(url, controller.signal, dependencies));
    const outcomes = tasks.map(task => task.then(() => true, () => false));
    await tick(); assert.equal(requests, 2); assert.equal(peak, 2);
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, dependencies));
    controllers.slice(2).forEach(controller => controller.abort());
    await Promise.all(outcomes.slice(2)); assert.equal(requests, 2);
    releases[0](); releases[1](true);
    assert.deepEqual(await Promise.all(outcomes.slice(0, 2)), [true, false]); await tick();
    assert.equal(active, 0); assert.equal(peak, 2);
    const retry = await loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input));
    assert.equal((await sharp(retry).metadata()).format, 'webp');
});

test('HTTP deadline returns promptly while the real native promise keeps the slot until it settles', async () => {
    const input = await png(), schedule = createCoverArtVariantScheduler(1, 1, 2, 2);
    let completeNative!: (output: Buffer) => void, started!: () => void;
    const nativeStarted = new Promise<void>(resolve => { started = resolve; });
    const actualNative = new Promise<Buffer>(resolve => { completeNative = resolve; });
    const keepAlive = setTimeout(() => undefined, 1000);
    try {
        const first = loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
            deadlineMs: 30, schedule,
            transform: async (_input, _type, _signal, timeoutSeconds) => {
                assert.ok(timeoutSeconds >= 1 && timeoutSeconds <= 8); started(); return actualNative;
            }
        }));
        const expired = assert.rejects(first);
        await nativeStarted;
        let secondRequestStarted = false;
        const second = loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
            schedule, request: async () => { secondRequestStarted = true; return { statusCode: 200, headers: { 'content-type': 'image/png' }, body: Readable.from([input]) }; }
        }));
        await expired; await tick();
        assert.equal(secondRequestStarted, false); assert.equal(schedule.snapshot().active, 1); assert.equal(schedule.snapshot().queued, 1);
        completeNative(Buffer.from('late-native-result'));
        assert.equal((await sharp(await second).metadata()).format, 'webp'); await tick();
        assert.equal(schedule.snapshot().active, 0); assert.equal(schedule.snapshot().queued, 0);
    } finally { clearTimeout(keepAlive); completeNative?.(Buffer.from('cleanup')); }
});

test('valid animated images, raster pixel bombs and SVG masquerading as PNG are rejected', async () => {
    const single = Buffer.from('R0lGODlhAQABAPAAAP///wAAACwAAAAAAQABAAACAkQBADs=', 'base64');
    const frame = single.indexOf(0x2c, 13);
    const animated = Buffer.concat([single.subarray(0, -1), single.subarray(frame)]);
    assert.equal((await sharp(animated).metadata()).pages, 2);
    const excessivePixels = await sharp({ create: { width: 4001, height: 4000, channels: 3, background: '#123456' } }).png().toBuffer();
    const svg = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="4" height="3"><rect width="4" height="3"/></svg>');
    for (const [input, contentType] of [[animated, 'image/gif'], [excessivePixels, 'image/png'], [svg, 'image/png']] as const) {
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
            request: async () => ({ statusCode: 200, headers: { 'content-type': contentType }, body: Readable.from([input]) })
        })));
    }
});

test('a safe HTTPS redirect repeats native DNS pinning and TLS checks without forwarding upstream cookies', async () => {
    const input = await png(), destination = 'https://cdn.example.test/current.png';
    const lookups: string[] = [], signals: AbortSignal[] = [], bodies: Readable[] = [];
    let requests = 0;
    const output = await loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async hostname => { lookups.push(hostname); return [{ address: hostname.startsWith('cdn.') ? '1.1.1.1' : address.address, family: 4 }]; },
        httpsRequest: ((target: URL, options: any, respond: (response: any) => void) => {
            requests++; signals.push(options.signal);
            assert.equal(options.servername, target.hostname); assert.equal(options.rejectUnauthorized, true);
            assert.deepEqual(Object.keys(options.headers).sort(), ['Accept', 'Accept-Encoding', 'User-Agent']);
            const expectedIp = target.hostname.startsWith('cdn.') ? '1.1.1.1' : address.address;
            options.lookup(target.hostname, { all: false }, (error: unknown, ip: string) => { assert.equal(error, null); assert.equal(ip, expectedIp); });
            const body = Readable.from([input]); bodies.push(body);
            const response = requests === 1
                ? { statusCode: 301, headers: { location: destination, 'set-cookie': 'must-not-forward=private' }, rawHeaders: ['Location', destination, 'Set-Cookie', 'must-not-forward=private'] }
                : { statusCode: 200, headers: { 'content-type': 'image/png' }, rawHeaders: ['Content-Type', 'image/png'] };
            const outgoing = new EventEmitter() as EventEmitter & { end: () => void };
            outgoing.end = () => respond(Object.assign(body, response));
            return outgoing;
        }) as NonNullable<LegacyArtworkDependencies['httpsRequest']>
    });
    assert.equal((await sharp(output).metadata()).format, 'webp');
    assert.deepEqual(lookups, ['images.example.test', 'cdn.example.test']); assert.equal(requests, 2);
    assert.equal(signals[0], signals[1]); assert.equal(bodies[0].destroyed, true);
});

test('all supported redirect codes accept relative HTTPS destinations and fully decode the final image', async () => {
    const input = await png();
    for (const status of [301, 302, 303, 307, 308]) {
        let count = 0;
        const output = await loadLegacyCatalogArtwork(url, new AbortController().signal, fixture(input, {
            request: async target => {
                count++;
                if (count === 1) return { statusCode: status, headers: { location: '/current.png' }, rawHeaders: ['Location', '/current.png'], body: Readable.from([]) };
                assert.equal(target.href, 'https://images.example.test/current.png');
                return { statusCode: 200, headers: { 'content-type': 'image/png' }, body: Readable.from([input]) };
            }
        }));
        assert.equal((await sharp(output).metadata()).format, 'webp'); assert.equal(count, 2);
    }
});

test('unsafe, missing or ambiguous redirect locations fail before a second connection', async () => {
    const cases = [
        { location: 'http://cdn.example.test/image.png' }, { location: 'https://127.0.0.1/image.png' },
        { location: 'https://user:password@cdn.example.test/image.png' }, { location: 'https://cdn.example.test:444/image.png' },
        { location: 'https://cdn.example.test/image.png#fragment' }, { location: '/bad\nlocation.png' },
        { location: '/bad\\location.png' }, { location: '/' + 'x'.repeat(2048) }, {},
        { location: ['https://cdn.example.test/a', 'https://cdn.example.test/b'] }
    ];
    for (const headers of cases) {
        let requests = 0; const body = Readable.from([]);
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
            lookup: async () => [address], request: async () => { requests++; return { statusCode: 302, headers: headers as any, body }; }
        }));
        assert.equal(requests, 1); assert.equal(body.destroyed, true);
    }
    let requests = 0;
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async () => [address], request: async () => { requests++; return { statusCode: 302,
            headers: { location: '/current.png' }, rawHeaders: ['Location', '/current.png', 'LOCATION', '/different.png'], body: Readable.from([]) }; }
    }));
    assert.equal(requests, 1);
});

test('redirect destinations with a private DNS answer and canonical URL loops never open another socket', async () => {
    let requests = 0; const lookups: string[] = [];
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async hostname => { lookups.push(hostname); return hostname.startsWith('private.') ? [address, { address: '169.254.169.254', family: 4 }] : [address]; },
        request: async () => { requests++; return { statusCode: 301, headers: { location: 'https://private.example.test/image.png' }, body: Readable.from([]) }; }
    }));
    assert.equal(requests, 1); assert.deepEqual(lookups, ['images.example.test', 'private.example.test']);
    requests = 0;
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async () => [address], request: async () => { requests++; return { statusCode: 301, headers: { location: 'https://IMAGES.example.test/legacy.png' }, body: Readable.from([]) }; }
    }));
    assert.equal(requests, 1);
});

test('redirects have one shared deadline and at most three followed destinations', async () => {
    let requests = 0;
    await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
        lookup: async () => [address], request: async () => { requests++; return { statusCode: 301, headers: { location: `/redirect-${requests}.png` }, body: Readable.from([]) }; }
    }));
    assert.equal(requests, 4);
    const keepAlive = setTimeout(() => undefined, 1000), signals: AbortSignal[] = [];
    const started = Date.now();
    try {
        await assert.rejects(loadLegacyCatalogArtwork(url, new AbortController().signal, {
            deadlineMs: 30, lookup: async () => [address], request: async (_url, _address, signal) => {
                signals.push(signal);
                if (signals.length === 1) {
                    await new Promise(resolve => setTimeout(resolve, 15));
                    return { statusCode: 301, headers: { location: '/current.png' }, body: Readable.from([]) };
                }
                return new Promise((_resolve, reject) => signal.addEventListener('abort', () => reject(new Error('expired')), { once: true }));
            }
        }));
        assert.equal(signals.length, 2); assert.equal(signals[0], signals[1]); assert.equal(signals[1].aborted, true);
        assert.ok(Date.now() - started < 1000);
    } finally { clearTimeout(keepAlive); }
});
